#!/usr/bin/env python3
"""Generated by stone render. Do not edit: change .cornerstone/config.yaml and render again.

PreToolUse hook: block a file-tool edit (not a Bash write) to a path that the current role must not change (P2).
The role comes from agent_type in the hook input, if it names a role of this hook. The harness sets
agent_type for a --agent session and in a subagent. Else the role comes from STONE_ROLE. The
default is implementer. Check K6 in CI is the source of truth.
A path is relative to the git work tree that holds it, so a linked worktree gets the same rules.
"""

import json
import os
import re
import subprocess
import sys
from pathlib import Path

# The implementer must not change PROTECTED. The tester changes only TESTS. The planner only PLANS.
# The shaper changes only the TICKET file, if the ticket is a file (#137).
# The investigator changes only REPORTS, except on a SPIKE_PREFIX branch, which never merges (K16).
# No branch lets the investigator change HARNESS: the hook, the checks, and the harness settings.
PROTECTED = ["**/*.test.js", ".claude/", ".cornerstone/", ".cornerstone/checks/", ".github/workflows/", "docs/specs/", "tests/"]
TESTS = ["tests/", "**/*.test.js"]
PLANS = ["docs/plans/"]
REPORTS = ["docs/reports/"]
HARNESS = [".claude/", ".cornerstone/"]
TICKET = ""  # the ticket file of the shaper (tickets.path). "" if the ticket is not a file.
SPIKE_PREFIX = "spike/"
ROLES = ("implementer", "tester", "planner", "investigator", "reviewer", "shaper")


# The path match of paths.tests and paths.checks. The hook and K6 get the same text (D62).
# A value with no glob character uses the prefix rule: the path, or a path under that folder.
# A glob starts at the repo root. `*`, `?`, and `[...]` match inside one folder level. A `**`
# level matches any number of levels, also zero. A glob also covers each path under a folder
# that it matches. compile_path raises ValueError for a glob that is not valid.
GLOB_CHARS = "*?["


def _glob_level(level: str, pattern: str) -> str:
    out, i = "", 0
    while i < len(level):
        char = level[i]
        if char == "*":
            out += "[^/]*"
            while i + 1 < len(level) and level[i + 1] == "*":
                i += 1
        elif char == "?":
            out += "[^/]"
        elif char == "[":
            start = i + 1 + (level[i + 1:i + 2] == "!")
            end = level.find("]", start + (level[start:start + 1] == "]"))
            if end == -1:
                raise ValueError(f"'{pattern}' has a '[' with no ']'.")
            body = level[start:end].replace("\\", "\\\\").replace("^", "\\^")
            out += ("[^" if start > i + 1 else "[") + body + "]"
            i = end
        else:
            out += re.escape(char)
        i += 1
    return out


def compile_path(pattern: str):
    """Return the regex of a glob, or None for a value with no glob character."""
    if not any(char in pattern for char in GLOB_CHARS):
        return None
    if pattern.startswith("/"):
        raise ValueError(f"'{pattern}' starts with '/'. Write it relative to the repo root.")
    levels = pattern.rstrip("/").split("/")
    if pattern.endswith("/"):
        levels.append("**")
    out = ""
    for number, level in enumerate(levels):
        last = number == len(levels) - 1
        if level == "**":
            out += ".*" if last else "(?:[^/]+/)*"
        else:
            out += _glob_level(level, pattern) + ("" if last else "/")
    return re.compile(out)


def covers(patterns: list[str], path: str) -> bool:
    """True if a value in patterns covers the repo path (a path with '/' between the levels)."""
    levels = path.split("/")
    for pattern in patterns:
        regex = compile_path(pattern)
        if regex is None:
            folder = pattern.rstrip("/")
            if path == folder or path.startswith(folder + "/"):
                return True
        elif any(regex.fullmatch("/".join(levels[:n])) for n in range(1, len(levels) + 1)):
            return True
    return False


def is_ticket(path: str) -> bool:
    pattern = re.escape(TICKET).replace(re.escape("{id}"), "[^/]+")
    return re.fullmatch(pattern, path) is not None


def find_role(event: dict) -> str:
    """Return agent_type if it names a role in ROLES, else STONE_ROLE, else implementer."""
    agent = event.get("agent_type")
    if agent in ROLES:
        return agent
    return os.environ.get("STONE_ROLE") or "implementer"


def git_tree(directory: Path) -> tuple[Path, Path] | None:
    """Return (top level, common git dir) of the work tree that holds directory, or None."""
    try:
        run = subprocess.run(["git", "-C", str(directory), "rev-parse", "--path-format=absolute",
                              "--show-toplevel", "--git-common-dir"],
                             capture_output=True, text=True, timeout=10)
    except (OSError, subprocess.SubprocessError):
        return None
    lines = run.stdout.splitlines()
    if run.returncode != 0 or len(lines) != 2:
        return None
    return Path(lines[0]).resolve(), Path(lines[1]).resolve()


def tree_root(file: Path, project: Path) -> Path:
    """Return the work tree that holds file if it is in the project repo, else project."""
    directory = next((parent for parent in file.parents if parent.is_dir()), project)
    tree, project_tree = git_tree(directory), git_tree(project)
    if tree and project_tree and tree[1] == project_tree[1]:
        return tree[0]
    return project


def on_spike_branch(tree: Path) -> bool:
    try:
        run = subprocess.run(["git", "-C", str(tree), "branch", "--show-current"],
                             capture_output=True, text=True, timeout=10)
    except (OSError, subprocess.SubprocessError):
        return False
    return run.returncode == 0 and run.stdout.strip().startswith(SPIKE_PREFIX)


def main() -> int:
    event = json.load(sys.stdin)
    tool_input = event.get("tool_input", {})
    target = tool_input.get("file_path") or tool_input.get("notebook_path")
    if not target:
        return 0
    project = Path(os.environ.get("CLAUDE_PROJECT_DIR") or event.get("cwd") or ".").resolve()
    file = Path(target).resolve()
    tree = tree_root(file, project)
    try:
        path = file.relative_to(tree).as_posix()
    except ValueError:
        return 0  # outside the repo
    role = find_role(event)
    if role == "implementer" and covers(PROTECTED, path):
        reason = "is a protected path. The implementer must not change tests, checks, or CI"
    elif role == "tester" and not covers(TESTS, path):
        reason = f"is not a test path. The tester changes only {', '.join(TESTS)}"
    elif role == "planner" and covers(PROTECTED, path):
        reason = "is a protected path. The planner must not change tests, checks, CI, or specs"
    elif role == "planner" and not covers(PLANS, path):
        reason = f"is not a plan path. The planner changes only {', '.join(PLANS)}"
    elif role == "investigator" and covers(HARNESS, path):
        reason = "is a harness or Cornerstone path. The investigator must not change it"
    elif role == "investigator" and not covers(REPORTS, path) and not on_spike_branch(tree):
        reason = (f"is not a report path. The investigator writes only in {', '.join(REPORTS)}, "
                  f"or on a {SPIKE_PREFIX} branch")
    elif role == "shaper" and TICKET and not is_ticket(path):
        reason = f"is not the ticket file. The shaper changes only {TICKET}"
    elif role == "reviewer":
        reason = "cannot change. The reviewer changes no file"
    else:
        return 0
    print(f"Blocked: {path} {reason}. Report the need in the decision log or the test report.",
          file=sys.stderr)
    return 2


if __name__ == "__main__":
    sys.exit(main())
